// 英単語の変化形（動詞の活用・名詞の複数形・形容詞と副詞の比較変化）を、見出し語の id ごと・品詞ごとに書いた台帳。
// 辞書ページと暗記カードの裏（WordStudyCard）の「変化形」の欄と、写真の読み取り（ocrWordForms.js）が使う。
//
// 対象は、品詞が名・動・形・副の全見出し語の代表の品詞と、意味欄の品詞の印（「報告(名)」）と
// ほかの意味（word-senses.js）で加わる品詞。つづりの規則・compromise・不規則形の表で下書きし、
// 全組を1語ずつ読んで、数えられるか・比較変化があるか・不規則な形を決めた（2026-11-26）。
// 見出し語や品詞を足したら、ここにも足す（tests/word-inflections-review.test.mjs が抜けを止める）。
//
// 書き方（形がいくつかあるときは / で区切り、アメリカ式を先に書く。イギリス式のつづりには 英 を付ける。
// # のあとは画面に添える注意書き）
//   動  '3単現|過去形|過去分詞|ing形'          runs|ran|run|running
//       '助:過去形'   助動詞（will → would）     '-'  変化しない（must）
//       'of:元の語:何の形'  見出し語そのものが別の語の変化形（is → be の3単現）
//   名  'C:複数形'   数えられる名詞              'CU:複数形'  数える使い方と数えない使い方がある
//       'U'  数えない（複数形にしない）  'SG'  ふつう a・the をつけて単数で使う
//       'PL' 複数形で使う・複数扱い     'P'  固有名詞・月の名前（複数形にしない）
//   形・副  '比較級|最上級'（more|most は前に more・most を置く形）  '-'  比較変化しない
//       'of:元の語:何の形'  見出し語そのものが別の語の比較級・最上級（better → good の比較級）
